package lk.ac.sliit.ridelink.ride.infrastructure.configuration;
import lk.ac.sliit.ridelink.ride.infrastructure.security.*; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.oauth2.jose.jws.MacAlgorithm; import org.springframework.security.oauth2.jwt.*; import org.springframework.security.oauth2.server.resource.authentication.*; import org.springframework.security.web.SecurityFilterChain; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.util.*;
@Configuration @EnableMethodSecurity public class SecurityConfiguration {
 @Bean JwtDecoder jwtDecoder(RideProperties p){byte[] secret=p.jwtSecret().getBytes(StandardCharsets.UTF_8);MacAlgorithm a=secret.length>=64?MacAlgorithm.HS512:secret.length>=48?MacAlgorithm.HS384:MacAlgorithm.HS256;String jca=a==MacAlgorithm.HS512?"HmacSHA512":a==MacAlgorithm.HS384?"HmacSHA384":"HmacSHA256";NimbusJwtDecoder d=NimbusJwtDecoder.withSecretKey(new SecretKeySpec(secret,jca)).macAlgorithm(a).build();d.setJwtValidator(JwtValidators.createDefaultWithIssuer(p.jwtIssuer()));return d;}
 @Bean JwtAuthenticationConverter jwtAuthenticationConverter(){JwtAuthenticationConverter c=new JwtAuthenticationConverter();c.setJwtGrantedAuthoritiesConverter(jwt->{String role=jwt.getClaimAsString("role");String type=jwt.getClaimAsString("token_type");if(role==null||(!"USER".equals(type)&&!("SERVICE".equals(type)&&"SERVICE".equals(role))))return List.of();return List.of(new org.springframework.security.core.authority.SimpleGrantedAuthority("ROLE_"+role));});return c;}
 @Bean SecurityFilterChain chain(HttpSecurity h,JwtAuthenticationConverter c,RestAuthenticationEntryPoint entry,RestAccessDeniedHandler denied)throws Exception{return h.csrf(x->x.disable()).sessionManagement(x->x.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).exceptionHandling(x->x.authenticationEntryPoint(entry).accessDeniedHandler(denied)).authorizeHttpRequests(x->x.requestMatchers("/v3/api-docs/**","/swagger-ui/**","/swagger-ui.html").permitAll().requestMatchers("/api/v1/internal/**").hasAnyRole("SERVICE","ADMIN").requestMatchers("/api/v1/rides/passenger/**").hasRole("PASSENGER").requestMatchers("/api/v1/rides/driver/**").hasRole("DRIVER").anyRequest().authenticated()).oauth2ResourceServer(x->x.jwt(j->j.jwtAuthenticationConverter(c)).authenticationEntryPoint(entry).accessDeniedHandler(denied)).build();}
}
